import { queryLimit, searchPattern } from "../http/query.ts";
import type { JsonRecord } from "../shared/types.ts";
import { callRpcRows } from "./postgrest.ts";

export type DashboardAdminActor = {
    userId: string;
    actorKind: "admin";
};

export type RefundDashboardRead = {
    refund: JsonRecord;
    client_reference_id: string;
};

export type DisputeDashboardRead = {
    dispute: JsonRecord;
    client_reference_id: string;
    staged_evidence: JsonRecord | null;
    evidence_submission_count: number;
    pending_approval: JsonRecord | null;
};

export type FinancialOperationDashboardRead = {
    operation: JsonRecord;
    client_reference_id: string | null;
    payment_currency: string | null;
};

export async function readRefundDashboardPage(
    request: Request,
    actor: DashboardAdminActor,
): Promise<RefundDashboardRead[]> {
    return await callRpcRows<RefundDashboardRead>("list_dashboard_refunds", {
        ...actorParams(actor),
        ...pageParams(request),
    });
}

export async function readDisputeDashboardPage(
    request: Request,
    actor: DashboardAdminActor,
): Promise<DisputeDashboardRead[]> {
    return await callRpcRows<DisputeDashboardRead>("read_dashboard_disputes", {
        ...actorParams(actor),
        ...pageParams(request),
        p_dispute_id: null,
    });
}

export async function readDisputeDashboardDetail(
    disputeId: string,
    actor: DashboardAdminActor,
): Promise<DisputeDashboardRead | null> {
    const rows = await callRpcRows<DisputeDashboardRead>("read_dashboard_disputes", {
        ...actorParams(actor),
        p_limit: 1,
        p_search: null,
        p_status: null,
        p_dispute_id: disputeId,
    });
    return rows[0] ?? null;
}

export async function readFinancialOperationDashboardPage(
    request: Request,
    actor: DashboardAdminActor,
): Promise<FinancialOperationDashboardRead[]> {
    return await callRpcRows<FinancialOperationDashboardRead>("list_dashboard_financial_operations", {
        ...actorParams(actor),
        ...pageParams(request),
    });
}

function pageParams(request: Request): {
    p_limit: number;
    p_search: string | null;
    p_status: string | null;
} {
    const params = new URL(request.url).searchParams;
    return {
        p_limit: queryLimit(params.get("limit")),
        p_search: searchPattern(params.get("q")),
        p_status: params.get("status")?.trim() || null,
    };
}

function actorParams(actor: DashboardAdminActor): {
    p_actor_id: string;
    p_actor_kind: "admin";
} {
    return { p_actor_id: actor.userId, p_actor_kind: actor.actorKind };
}

import { connectSchema, requiredEnv, serviceRoleKey } from "../shared/runtime.ts";
import { HttpError } from "../http/errors.ts";
import { isRecord, stripUndefined } from "../shared/data.ts";
import type { JsonRecord } from "../shared/types.ts";

export async function rest(path: string, init: RequestInit): Promise<Response> {
    const key = serviceRoleKey();
    const base = requiredEnv("SUPABASE_URL").replace(/\/$/, "");
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    headers.set("authorization", `Bearer ${key}`);
    headers.set("accept-profile", connectSchema);
    if (init.method && init.method !== "GET") {
        headers.set("content-profile", connectSchema);
    }
    return fetch(`${base}/rest/v1/${path}`, { ...init, headers });
}

export async function restError(response: Response): Promise<HttpError> {
    const data = await response.json().catch(() => null);
    const message =
        isRecord(data) && typeof data.message === "string"
            ? data.message
            : `Supabase request failed (${response.status})`;
    if (message.startsWith("validation:")) {
        return new HttpError(400, message.slice("validation:".length).trim());
    }
    if (message.startsWith("not_found:")) {
        return new HttpError(404, message.slice("not_found:".length).trim());
    }
    if (message.startsWith("conflict:")) {
        return new HttpError(409, message.slice("conflict:".length).trim());
    }
    if (message.startsWith("forbidden:")) {
        return new HttpError(403, message.slice("forbidden:".length).trim());
    }
    return new HttpError(502, message);
}

export async function insertRow<T>(table: string, select: string, values: JsonRecord): Promise<T> {
    const response = await rest(`${table}?select=${encodeURIComponent(select)}`, {
        method: "POST",
        headers: { "content-type": "application/json", prefer: "return=representation" },
        body: JSON.stringify(stripUndefined(values)),
    });
    if (!response.ok) {
        throw await restError(response);
    }
    return firstRow<T>(await response.json());
}

export async function upsertRow<T>(
    table: string,
    conflictField: string,
    select: string,
    values: JsonRecord,
): Promise<T> {
    const response = await rest(
        `${table}?on_conflict=${encodeURIComponent(conflictField)}&select=${encodeURIComponent(select)}`,
        {
            method: "POST",
            headers: {
                "content-type": "application/json",
                prefer: "resolution=merge-duplicates,return=representation",
            },
            body: JSON.stringify(stripUndefined(values)),
        },
    );
    if (!response.ok) {
        throw await restError(response);
    }
    return firstRow<T>(await response.json());
}

export async function updateRow<T = JsonRecord>(
    table: string,
    id: number,
    values: JsonRecord,
    select = "*",
): Promise<T | null> {
    const response = await rest(`${table}?id=eq.${id}&select=${encodeURIComponent(select)}`, {
        method: "PATCH",
        headers: { "content-type": "application/json", prefer: "return=representation" },
        body: JSON.stringify(stripUndefined(values)),
    });
    if (!response.ok) {
        throw await restError(response);
    }
    const rows = (await response.json()) as T[];
    return rows[0] ?? null;
}

export async function getRowByField<T>(table: string, field: string, value: string, select: string): Promise<T | null> {
    const response = await rest(
        `${table}?${field}=eq.${encodeURIComponent(value)}&select=${encodeURIComponent(select)}&limit=1`,
        { method: "GET" },
    );
    if (!response.ok) {
        throw await restError(response);
    }
    const rows = (await response.json()) as T[];
    return rows[0] ?? null;
}

export async function listRows<T>(path: string): Promise<T[]> {
    const response = await rest(path, { method: "GET" });
    if (!response.ok) {
        throw await restError(response);
    }
    return (await response.json()) as T[];
}

export async function callRpcRows<T>(name: string, body: JsonRecord): Promise<T[]> {
    const response = await rest(`rpc/${name}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
    });
    if (!response.ok) {
        throw await restError(response);
    }
    return (await response.json()) as T[];
}

export async function callRpcObject<T>(name: string, body: JsonRecord): Promise<T> {
    const response = await rest(`rpc/${name}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
    });
    if (!response.ok) {
        throw await restError(response);
    }
    const value = await response.json();
    return (isRecord(value) ? value : firstRow<T>(value)) as T;
}

export function firstRow<T>(value: unknown): T {
    if (!Array.isArray(value) || !value[0]) {
        throw new HttpError(502, "Supabase returned no rows");
    }
    return value[0] as T;
}

import type { JsonRecord } from "../shared/types.ts";
import { callRpcObject, callRpcRows, rest, restError } from "./postgrest.ts";

export type ReconciliationOperationRead = {
