import { HttpError } from "../../http/errors.ts";
import { isRecord } from "../../shared/data.ts";
import type { JsonRecord } from "../../shared/types.ts";
import { callRpcObject } from "../postgrest.ts";
import type { ConnectAccountRow } from "../records/accounts.ts";
import type { TransferRow } from "../records/transfers.ts";

export type SettlementReleaseContext = {
    sellerAccount: ConnectAccountRow | null;
    existingTransfer: TransferRow | null;
    sellerRecoveryAmount: number;
};

export type SettlementReleaseLedger = {
    transferredAmount: number;
    reversedAmount: number;
    sellerRecoveryAmount: number;
};

export async function readSettlementReleaseContext(
    paymentId: number,
    sellerCmsUserId: string,
    releaseAuthorizationId: string,
): Promise<SettlementReleaseContext> {
    const value = await callRpcObject<unknown>("read_settlement_release_context", {
        p_payment_id: paymentId,
        p_seller_cms_user_id: sellerCmsUserId,
        p_release_authorization_id: releaseAuthorizationId,
    });
    if (!isRecord(value)) {
        throw invalidSettlementRead("context");
    }
    const sellerAccount = nullableRecord(value.seller_account, "context");
    const existingTransfer = nullableRecord(value.existing_transfer, "context");
    if (sellerAccount && !isSettlementSeller(sellerAccount)) {
        throw invalidSettlementRead("context");
    }
    if (existingTransfer && !isSettlementTransfer(existingTransfer)) {
        throw invalidSettlementRead("context");
    }
    return {
        sellerAccount: sellerAccount as unknown as ConnectAccountRow | null,
        existingTransfer: existingTransfer as unknown as TransferRow | null,
        sellerRecoveryAmount: amountAt(value, "seller_recovery_amount", "context"),
    };
}

export async function readSettlementReleaseLedger(paymentId: number): Promise<SettlementReleaseLedger> {
    const value = await callRpcObject<unknown>("read_settlement_release_ledger", {
        p_payment_id: paymentId,
    });
    if (!isRecord(value)) {
        throw invalidSettlementRead("ledger");
    }
    return {
        transferredAmount: amountAt(value, "transferred_amount", "ledger"),
        reversedAmount: amountAt(value, "reversed_amount", "ledger"),
        sellerRecoveryAmount: amountAt(value, "seller_recovery_amount", "ledger"),
    };
}

function nullableRecord(value: unknown, source: string): JsonRecord | null {
    if (value === null) {
        return null;
    }
    if (!isRecord(value)) {
        throw invalidSettlementRead(source);
    }
    return value;
}

function amountAt(value: JsonRecord, key: string, source: string): number {
    const amount = value[key];
    if (typeof amount !== "number" || !Number.isSafeInteger(amount) || amount < 0) {
        throw invalidSettlementRead(source);
    }
    return amount;
}

function isSettlementSeller(value: JsonRecord): boolean {
    return (
        typeof value.cms_user_id === "string" &&
        (value.stripe_account_id === null || typeof value.stripe_account_id === "string") &&
        typeof value.stripe_account_api_version === "string" &&
        typeof value.application_controlled_recipient === "boolean" &&
        typeof value.terms_accepted === "boolean" &&
        typeof value.provider_account_closed === "boolean" &&
        (value.marketplace_terms_accepted_at === null || typeof value.marketplace_terms_accepted_at === "string") &&
        typeof value.onboarding_status === "string" &&
        typeof value.details_submitted === "boolean" &&
        isRecord(value.capabilities) &&
        Array.isArray(value.requirements_currently_due) &&
        Array.isArray(value.requirements_past_due) &&
        Array.isArray(value.requirements_pending_verification) &&
        typeof value.risk_status === "string" &&
        typeof value.outstanding_debt_amount === "number" &&
        typeof value.financial_exposure_amount === "number" &&
        (value.financial_hold_reason === null || typeof value.financial_hold_reason === "string") &&
        (value.manual_payout_hold_started_at === null || typeof value.manual_payout_hold_started_at === "string")
    );
}

function isSettlementTransfer(value: JsonRecord): boolean {
    return (
        typeof value.id === "number" &&
        typeof value.payment_id === "number" &&
        typeof value.operation_id === "number" &&
        typeof value.release_authorization_id === "string" &&
        typeof value.release_kind === "string" &&
        (value.stripe_transfer_id == null || typeof value.stripe_transfer_id === "string") &&
        (value.source_charge_id == null || typeof value.source_charge_id === "string") &&
        typeof value.destination_account_id === "string" &&
        typeof value.transfer_group === "string" &&
        typeof value.amount === "number" &&
        typeof value.currency === "string" &&
        typeof value.status === "string" &&
        typeof value.created_at === "string" &&
        typeof value.updated_at === "string"
    );
}

function invalidSettlementRead(source: string): HttpError {
    return new HttpError(502, `settlement release ${source} returned an invalid response`);
}

import { HttpError } from "../../http/errors.ts";
import { isRecord } from "../../shared/data.ts";
import type { JsonRecord } from "../../shared/types.ts";
import { firstRow, rest, restError } from "../postgrest.ts";
import type { FinancialOperationRow } from "../records/operations.ts";
import type {
    ReservedTransferRecovery,
    TransferRecoveryRow,
    TransferReversalRow,
    TransferRow,
} from "../records/transfers.ts";

export async function reserveTransferRecovery(
    paymentId: number,
    recoveryRequestId: string,
    amount: number,
    exposureType: TransferRecoveryRow["exposure_type"],
    reason: string | null,
): Promise<ReservedTransferRecovery> {
    const response = await rest("rpc/reserve_transfer_recovery", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
            p_payment_id: paymentId,
            p_recovery_request_id: recoveryRequestId,
            p_amount: amount,
            p_exposure_type: exposureType,
            p_reason: reason,
        }),
    });
    if (!response.ok) {
        throw await restError(response);
    }
    const value = await response.json();
    const result = isRecord(value) ? value : firstRow<JsonRecord>(value);
    const recovery = result.recovery;
    const allocations = result.allocations;
    if (!isRecord(recovery) || !Array.isArray(allocations)) {
        throw new HttpError(502, "Supabase returned an invalid Transfer recovery reservation");
    }
    return {
        recovery: recovery as TransferRecoveryRow,
        allocations: allocations.map((allocation) => {
            if (
                !isRecord(allocation) ||
                !isRecord(allocation.reversal) ||
                !isRecord(allocation.operation) ||
                !isRecord(allocation.transfer)
            ) {
                throw new HttpError(502, "Supabase returned an invalid Transfer recovery allocation");
            }
            return {
                reversal: allocation.reversal as TransferReversalRow,
                operation: allocation.operation as FinancialOperationRow,
                transfer: allocation.transfer as TransferRow,
            };
        }),
    };
}

import type { ConnectAccountRow } from "../../db/records/accounts.ts";
import { objectAt } from "../../shared/data.ts";

export function sellerCanReceivePayments(account: ConnectAccountRow): boolean {
    return Boolean(
        account.stripe_account_id &&
            account.stripe_account_api_version === "v2" &&
            account.terms_accepted &&
            Boolean(account.marketplace_terms_accepted_at) &&
            !account.provider_account_closed &&
            account.onboarding_status === "enabled" &&
            stripeTransfersStatus(account) === "active" &&
            account.details_submitted &&
            account.application_controlled_recipient &&
            account.requirements_currently_due.length === 0 &&
            account.requirements_past_due.length === 0 &&
            account.requirements_pending_verification.length === 0 &&
            !["restricted", "blocked", "manual_review"].includes(account.risk_status) &&
            account.outstanding_debt_amount === 0 &&
            account.financial_exposure_amount === 0 &&
            !account.financial_hold_reason &&
            !account.manual_payout_hold_started_at,
    );
}

export function sellerCanAcceptHeldPayments(account: ConnectAccountRow): boolean {
    return Boolean(
        account.stripe_account_id &&
            account.stripe_account_api_version === "v2" &&
            account.application_controlled_recipient &&
            account.terms_accepted &&
            account.terms_accepted &&
            Boolean(account.marketplace_terms_accepted_at) &&
            !account.provider_account_closed &&
            account.onboarding_status !== "rejected" &&
            !["restricted", "blocked", "manual_review"].includes(account.risk_status) &&
            account.outstanding_debt_amount === 0 &&
            account.financial_exposure_amount === 0 &&
            !account.financial_hold_reason &&
            !account.manual_payout_hold_started_at,
    );
}

export function sellerStripeEnrollmentReady(account: ConnectAccountRow): boolean {
    return Boolean(
        account.stripe_account_id &&
            account.stripe_account_api_version === "v2" &&
            account.application_controlled_recipient &&
            account.terms_accepted &&
            !account.provider_account_closed &&
            account.onboarding_status !== "rejected",
    );
}

export function stripeTransfersStatus(account: ConnectAccountRow): string {
    if (account.stripe_account_api_version === "v1") {
        return (
            normalizedCapabilityStatus(account.capabilities.transfers) ||
            (account.payouts_enabled ? "active" : "unrequested")
        );
    }
    const stripeBalance = objectAt(account.capabilities, "stripe_balance");
    return normalizedCapabilityStatus(objectAt(stripeBalance, "stripe_transfers").status) || "unrequested";
}

export function bankPayoutsStatus(account: ConnectAccountRow): string {
    if (account.stripe_account_api_version === "v1") {
        return account.payouts_enabled ? "active" : "unrequested";
    }
    const stripeBalance = objectAt(account.capabilities, "stripe_balance");
    return normalizedCapabilityStatus(objectAt(stripeBalance, "payouts").status) || "unrequested";
}

function normalizedCapabilityStatus(value: unknown): string {
    return typeof value === "string" &&
        ["active", "pending", "restricted", "unsupported", "unrequested"].includes(value)
        ? value
        : "";
}

export function sellerEnrollmentStatus(account: ConnectAccountRow): string {
    if (!account.stripe_account_id) {
        return "not_started";
    }
    if (account.provider_account_closed || account.onboarding_status === "rejected") {
        return "rejected";
    }
    if (account.stripe_account_api_version !== "v2" || !account.application_controlled_recipient) {
        return "rejected";
    }
    if (!account.terms_accepted || !account.marketplace_terms_accepted_at) {
        return "terms_required";
    }
    return "enrolled";
}

import type { ConnectAccountRow } from "../../db/records/accounts.ts";
import type { PlatformPayoutControlRow } from "../../db/records/operations.ts";
import { objectAt } from "../../shared/data.ts";
import type { JsonRecord } from "../../shared/types.ts";

export function platformPayoutControl(result: JsonRecord): PlatformPayoutControlRow {
    const control = objectAt(result, "control") as unknown as PlatformPayoutControlRow;
    if (
        control.control_key !== "default" ||
        !Number.isSafeInteger(control.liability_revision) ||
        !Number.isSafeInteger(control.required_minimum_amount) ||
        !Number.isSafeInteger(control.provider_minimum_amount)
    ) {
        throw new Error("Platform payout protection RPC returned invalid state");
    }
    return control;
}

export function sellerRiskAccount(result: JsonRecord): ConnectAccountRow {
    const account = objectAt(result, "account") as unknown as ConnectAccountRow;
    if (!account.cms_user_id) {
        throw new Error("Seller payout hold RPC returned no account");
    }
    return account;
}

import type { StripeBalanceSettings } from "../../provider/types.ts";
import { arrayAt, objectAt, stringArrayAt, stringAt } from "../../shared/data.ts";
import type { JsonRecord } from "../../shared/types.ts";

export function publicBalanceSettings(
    balanceSettings: StripeBalanceSettings,
    fallbackInterval = "stripe_default",
): JsonRecord {
    const payments = objectAt(balanceSettings, "payments");
    const payouts = objectAt(payments, "payouts");
    const schedule = objectAt(payouts, "schedule");
    const settlementTiming = objectAt(payments, "settlement_timing");
    return {
        interval: stringAt(schedule, "interval") || fallbackInterval,
        weeklyPayoutDays: stringArrayAt(schedule, "weekly_payout_days"),
        monthlyPayoutDays: arrayAt(schedule, "monthly_payout_days").filter((value): value is number =>
            Number.isSafeInteger(value),
        ),
        minimumBalanceByCurrency: objectAt(payouts, "minimum_balance_by_currency"),
        debitNegativeBalances:
            typeof payments.debit_negative_balances === "boolean" ? payments.debit_negative_balances : null,
        delayDays: Number.isSafeInteger(settlementTiming.delay_days) ? settlementTiming.delay_days : null,
        delayDaysOverride: Number.isSafeInteger(settlementTiming.delay_days_override)
            ? settlementTiming.delay_days_override
            : null,
        status: stringAt(payouts, "status") || null,
    };
}

export function balanceSettingsMatchRequest(settings: StripeBalanceSettings, request: JsonRecord): boolean {
    const payments = objectAt(settings, "payments");
    const payouts = objectAt(payments, "payouts");
    const schedule = objectAt(payouts, "schedule");
    if (stringAt(schedule, "interval") !== request.interval) {
        return false;
    }
    if (Array.isArray(request.weeklyPayoutDays)) {
        if (!sameScalarSet(stringArrayAt(schedule, "weekly_payout_days"), request.weeklyPayoutDays)) {
            return false;
        }
    }
    if (Array.isArray(request.monthlyPayoutDays)) {
        const actual = arrayAt(schedule, "monthly_payout_days").filter((value) => Number.isSafeInteger(value));
        if (!sameScalarSet(actual, request.monthlyPayoutDays)) {
            return false;
        }
    }
    if (Number.isSafeInteger(request.minimumBalanceEur)) {
        const providerMinimum = objectAt(payouts, "minimum_balance_by_currency").eur;
        const normalizedProviderMinimum =
            providerMinimum === null || providerMinimum === undefined ? 0 : providerMinimum;
        if (normalizedProviderMinimum !== request.minimumBalanceEur) {
            return false;
        }
    }
    if (Number.isSafeInteger(request.delayDaysOverride)) {
        if (objectAt(payments, "settlement_timing").delay_days_override !== request.delayDaysOverride) {
            return false;
        }
    }
    if (typeof request.debitNegativeBalances === "boolean") {
        if (payments.debit_negative_balances !== request.debitNegativeBalances) {
            return false;
        }
    }
    return true;
}

function sameScalarSet(left: unknown[], right: unknown[]): boolean {
    const normalize = (values: unknown[]) => values.map(String).sort();
    return JSON.stringify(normalize(left)) === JSON.stringify(normalize(right));
}

