    getMarketplaceTermsAcceptance,
    recordMarketplaceTermsAcceptance,
} from "../../db/repositories/accounts.ts";
import {
    effectiveMarketplaceTermsExpectation,
    getCurrentMarketplaceTermsConfiguration,
    marketplaceTermsRequirement,
    recordCurrentMarketplaceTermsAcceptance,
} from "./marketplace-terms/repository.ts";
import { sellerStripeEnrollmentReady } from "../../domain/accounts/eligibility.ts";
import { publicAccount } from "../../domain/accounts/presentation.ts";
import { requireCmsRequest } from "../../http/auth.ts";
import {
    assertAllowedKeys,
    marketplaceTermsAcceptanceExpectationFromBody,
    marketplaceTermsExpectationFromBody,
    optionalEmail,
    readJsonObject,
    requiredStripeToken,
} from "../../http/body/index.ts";
import { HttpError } from "../../http/errors.ts";
import { json } from "../../http/responses.ts";
import type { JsonRecord } from "../../shared/types.ts";
import { submitCustomVerificationForUser } from "./lifecycle.ts";
import { syncAccountForUser } from "./sync.ts";

export async function connectEnrollment(request: Request): Promise<Response> {
    const { userId } = requireCmsRequest(request);
    const body = await readJsonObject(request);
    return json(await enrollSellerForUser(userId, body));
}

export async function connectVerification(request: Request): Promise<Response> {
    const { userId } = requireCmsRequest(request);
    const body = await readJsonObject(request);
    assertAllowedKeys(body, [
        "accountToken",
        "bankAccountToken",
        "contactEmail",
        "marketplaceTermsAccepted",
        "expectedMarketplaceTermsVersion",
        "expectedMarketplaceTermsHash",
    ]);
    const hasMarketplaceTermsSubmission = [
        "marketplaceTermsAccepted",
        "expectedMarketplaceTermsVersion",
        "expectedMarketplaceTermsHash",
    ].some((key) => body[key] !== undefined);
    if (!hasMarketplaceTermsSubmission) {
        return json(await submitCustomVerificationForUser(userId, verificationBody(body)));
    }
    const explicitlyAccepted = body.marketplaceTermsAccepted === true;
    if (body.marketplaceTermsAccepted !== undefined && !explicitlyAccepted) {
        throw new HttpError(400, "marketplaceTermsAccepted must be true when provided");
    }
    const acceptanceExpectation = marketplaceTermsAcceptanceExpectationFromBody(body);
    if (acceptanceExpectation && !explicitlyAccepted) {
        throw new HttpError(400, "expected marketplace terms evidence requires explicit acceptance");
    }
    const configuredTerms = await getCurrentMarketplaceTermsConfiguration();
    if (
        explicitlyAccepted &&
        (!configuredTerms ||
            !acceptanceExpectation ||
            acceptanceExpectation.version !== configuredTerms.version ||
            acceptanceExpectation.hash !== configuredTerms.hash)
    ) {
        throw new HttpError(409, "MARKETPLACE_TERMS_VERSION_CHANGED");
    }
    await submitCustomVerificationForUser(userId, verificationBody(body));
    if (explicitlyAccepted) {
        await recordCurrentMarketplaceTermsAcceptance(userId, acceptanceExpectation);
    }
    const account = await getAccountRow(userId);
    if (!account) {
        throw new HttpError(502, "could not reload the verified seller account");
    }
    const recordedTerms = configuredTerms
        ? await getMarketplaceTermsAcceptance(userId, configuredTerms.version, configuredTerms.hash)
        : null;
    return json(
        publicAccount(account, {
            currentTermsAccepted: Boolean(recordedTerms),
            ...(configuredTerms ? { marketplaceTermsRequirement: marketplaceTermsRequirement(configuredTerms) } : {}),
        }),
    );
}

async function enrollSellerForUser(userId: string, body: JsonRecord): Promise<JsonRecord> {
    assertAllowedKeys(body, [
        "accountToken",
        "contactEmail",
        "marketplaceTermsAccepted",
        "marketplaceTermsVersion",
        "marketplaceTermsHash",
        "expectedMarketplaceTermsVersion",
        "expectedMarketplaceTermsHash",
    ]);
    const explicitTerms = marketplaceTermsExpectationFromBody(body);
    const acceptanceExpectation = marketplaceTermsAcceptanceExpectationFromBody(body);
    const explicitlyAccepted = body.marketplaceTermsAccepted === true;
    if (body.marketplaceTermsAccepted !== undefined && !explicitlyAccepted) {
        throw new HttpError(400, "marketplaceTermsAccepted must be true when provided");
    }
    const configuredTerms = await getCurrentMarketplaceTermsConfiguration();
    const expectedTerms = effectiveMarketplaceTermsExpectation(explicitTerms, configuredTerms);
    if (explicitlyAccepted && !expectedTerms) {
        throw new HttpError(
            400,
            "marketplaceTermsVersion and marketplaceTermsHash are required with marketplaceTermsAccepted",
        );
    }
    if (acceptanceExpectation && !explicitlyAccepted) {
        throw new HttpError(400, "expected marketplace terms evidence requires explicit acceptance");
    }
    if (
        explicitlyAccepted &&
        acceptanceExpectation &&
        (acceptanceExpectation.version !== expectedTerms?.version || acceptanceExpectation.hash !== expectedTerms?.hash)
    ) {
        throw new HttpError(409, "MARKETPLACE_TERMS_VERSION_CHANGED");
    }
    if (explicitlyAccepted && configuredTerms?.mode === "published_page" && !acceptanceExpectation) {
        throw new HttpError(409, "MARKETPLACE_TERMS_VERSION_CHANGED");
    }
    const acceptsConfiguredTerms =
        Boolean(configuredTerms) &&
        configuredTerms?.version === expectedTerms?.version &&
        configuredTerms?.hash === expectedTerms?.hash;
    let current = await syncAccountForUser(userId);
    let recordedTerms =
        current && expectedTerms
            ? await getMarketplaceTermsAcceptance(userId, expectedTerms.version, expectedTerms.hash)
            : null;

    if (!recordedTerms && !explicitlyAccepted && !(current?.marketplace_terms_accepted_at && !expectedTerms)) {
        throw new HttpError(409, "current marketplace terms acceptance is required");
    }

    if (!current || !sellerStripeEnrollmentReady(current)) {
        const accountToken = requiredStripeToken(body, "accountToken", "accttok_");
        const contactEmail = optionalEmail(body, "contactEmail");
        await submitCustomVerificationForUser(userId, {
            accountToken,
            ...(contactEmail ? { contactEmail } : {}),
        });
        current = await syncAccountForUser(userId);
        if (!current || !sellerStripeEnrollmentReady(current)) {
            throw new HttpError(409, "Stripe identity and terms acceptance were not confirmed");
        }
    }

    if (expectedTerms && explicitlyAccepted && !recordedTerms) {
        recordedTerms = acceptsConfiguredTerms
            ? await recordCurrentMarketplaceTermsAcceptance(userId, acceptanceExpectation)
            : await recordMarketplaceTermsAcceptance(userId, expectedTerms.version, expectedTerms.hash);
        current = await getAccountRow(userId);
        if (!current) {
            throw new HttpError(502, "could not reload the enrolled seller account");
        }
    }

    return publicAccount(current, {
        currentTermsAccepted: Boolean(expectedTerms && recordedTerms),
        marketplaceTermsRequirement: marketplaceTermsRequirement(configuredTerms),
    });
}

function verificationBody(body: JsonRecord): JsonRecord {
    return Object.fromEntries(
        ["accountToken", "bankAccountToken", "contactEmail"]
            .filter((key) => body[key] !== undefined)
            .map((key) => [key, body[key]]),
    );
}

import { defaultCountry } from "../../shared/runtime.ts";
import { getAccountRow, updateAccountRow, upsertAccountRow } from "../../db/repositories/accounts.ts";
import type { ConnectAccountRow } from "../../db/records/accounts.ts";
import { publicAccount } from "../../domain/accounts/presentation.ts";
import { accountPatchFromStripe } from "../../domain/accounts/provider-projection.ts";
import {
    assertApplicationControlledRecipient,
    isApplicationCollectedAccount,
} from "../../domain/accounts/stripe-v2.ts";
import {
    assertOnlyKeys,
    optionalCountry,
    optionalEmail,
    optionalStripeToken,
    optionalText,
} from "../../http/body/index.ts";
import { HttpError } from "../../http/errors.ts";
import {
    createConnectedAccount,
    createCustomConnectedAccount,
    retrieveAccount,
    updateCustomConnectedAccount,
} from "../../provider/accounts/lifecycle.ts";
import { attachBankAccount } from "../../provider/accounts/onboarding.ts";
import type { StripeAccount, StripeAccountApiVersion } from "../../provider/types.ts";
import type { JsonRecord } from "../../shared/types.ts";

export async function ensureConnectedAccountForUser(
    userId: string,
    body: JsonRecord,
): Promise<{
    account: ConnectAccountRow;
    stripeAccountId: string;
    stripeAccountApiVersion: StripeAccountApiVersion;
}> {
    const email = optionalEmail(body, "email");
    const displayName = optionalText(body, "displayName", 200);
    const country = defaultCountry();
    const requestedCountry = optionalCountry(body, "country");
    if (requestedCountry && requestedCountry !== country) {
        throw new HttpError(400, `country must be ${country} for this integration version`);
    }

    let account = await getAccountRow(userId);
    let stripeAccountId = account?.stripe_account_id ?? null;
    let stripeAccountApiVersion: StripeAccountApiVersion = account?.stripe_account_api_version ?? "v1";
    if (!stripeAccountId) {
        if (!email) {
            throw new HttpError(400, "email is required to create a Stripe recipient account");
        }
        const stripeAccount = await createConnectedAccount({
            userId,
            country,
            email,
            displayName,
        });
        assertApplicationControlledRecipient(stripeAccount);
        stripeAccountId = stripeAccount.id;
        stripeAccountApiVersion = "v2";
        account = await upsertAccountRow({
            cms_user_id: userId,
            stripe_account_api_version: stripeAccountApiVersion,
            ...accountPatchFromStripe(stripeAccount, stripeAccountApiVersion),
        });
    } else {
        let stripeAccount = await retrieveAccount(stripeAccountId, stripeAccountApiVersion);
        if (stripeAccountApiVersion !== "v2" || !isApplicationCollectedAccount(stripeAccount)) {
            if (!email) {
                throw new HttpError(409, "email is required to replace a recipient account with unsafe payout access");
            }
            stripeAccount = await createConnectedAccount({
                userId,
                country,
                email,
                displayName,
            });
            assertApplicationControlledRecipient(stripeAccount);
            stripeAccountId = stripeAccount.id;
            stripeAccountApiVersion = "v2";
            account = await upsertAccountRow({
                cms_user_id: userId,
                stripe_account_api_version: stripeAccountApiVersion,
                ...accountPatchFromStripe(stripeAccount, stripeAccountApiVersion),
            });
        } else {
            account = await updateAccountRow(userId, accountPatchFromStripe(stripeAccount, stripeAccountApiVersion));
        }
    }

    if (!stripeAccountId) {
        throw new HttpError(502, "could not create connected account");
    }
    if (!account) {
        throw new HttpError(502, "could not store connected account");
    }
    return { account, stripeAccountId, stripeAccountApiVersion };
}

export async function submitCustomVerificationForUser(userId: string, body: JsonRecord): Promise<JsonRecord> {
    assertOnlyKeys(body, ["accountToken", "bankAccountToken", "contactEmail"]);
    const accountToken = optionalStripeToken(body, "accountToken", "accttok_");
    const bankAccountToken = optionalStripeToken(body, "bankAccountToken", "btok_");
    optionalEmail(body, "contactEmail");
    let row = await getAccountRow(userId);
    let stripeAccount: StripeAccount | null = null;

    if (row?.stripe_account_id) {
        stripeAccount = await retrieveAccount(row.stripe_account_id, row.stripe_account_api_version);
    }

    const replaceAccount =
        !row?.stripe_account_id ||
        row.stripe_account_api_version !== "v2" ||
        !isApplicationCollectedAccount(stripeAccount);

    if (replaceAccount) {
        if (!accountToken) {
            throw new HttpError(400, "accountToken is required for initial Stripe identity enrollment");
        }
        const currentPatch =
            stripeAccount && row ? accountPatchFromStripe(stripeAccount, row.stripe_account_api_version) : null;
        if (currentPatch?.payouts_enabled === true && currentPatch.details_submitted === true) {
            throw new HttpError(
                409,
                "A fully active legacy Stripe account cannot be replaced through seller verification",
            );
        }
        stripeAccount = await createCustomConnectedAccount(userId, accountToken);
        row = await upsertAccountRow({
            cms_user_id: userId,
            stripe_account_api_version: "v2",
            ...accountPatchFromStripe(stripeAccount, "v2"),
        });
    } else if (accountToken) {
        stripeAccount = await updateCustomConnectedAccount(row!.stripe_account_id!, accountToken);
    }

    if (!stripeAccount?.id) {
        throw new HttpError(502, "Stripe did not return a connected account");
    }
    if (bankAccountToken) {
        await attachBankAccount(stripeAccount.id, bankAccountToken);
    }
    stripeAccount = await retrieveAccount(stripeAccount.id, "v2");
    row = await upsertAccountRow({
        cms_user_id: userId,
        stripe_account_api_version: "v2",
        ...(bankAccountToken ? { external_bank_account_attached: true } : {}),
        ...accountPatchFromStripe(stripeAccount, "v2"),
    });
    return publicAccount(row);
}

export type PublishedPage = {
    id: string;
    path: string;
    title: string;
    description: string;
    content: string;
};

export async function sha256Hex(value: string): Promise<string> {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
    return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

export async function publishedPageContentHash(page: PublishedPage): Promise<string> {
    return sha256Hex(serializePublishedPage(page));
}

export function serializePublishedPage(page: PublishedPage): string {
    return JSON.stringify({
        id: page.id,
        path: page.path,
        title: page.title,
        description: page.description,
        content: page.content,
    });
}

import { requireCmsRequest } from "../../../http/auth.ts";
import { assertAllowedKeys, readJsonObject } from "../../../http/body/index.ts";
import { HttpError } from "../../../http/errors.ts";
import { json } from "../../../http/responses.ts";
import { isRecord } from "../../../shared/data.ts";
import type { JsonRecord } from "../../../shared/types.ts";
import { serializePublishedPage, sha256Hex } from "./canonical-page.ts";
import { syncMarketplaceTermsConfiguration } from "./repository.ts";
import { materializePublishedMarketplaceTerms } from "./snapshot.ts";

const maximumConfigurationBytes = 8_388_608;

export async function configureMarketplaceTerms(request: Request): Promise<Response> {
    requireCmsRequest(request, { requireUser: false });
    const declaredLength = Number(request.headers.get("content-length"));
    if (Number.isFinite(declaredLength) && declaredLength > maximumConfigurationBytes) {
        throw new HttpError(400, "marketplace terms configuration must not exceed 8 MiB");
    }
    const body = await readJsonObject(request);
    assertAllowedKeys(body, ["documents", "legacyVersion", "legacyHash"]);
    if (new TextEncoder().encode(JSON.stringify(body)).byteLength > maximumConfigurationBytes) {
        throw new HttpError(400, "marketplace terms configuration must not exceed 8 MiB");
    }
    const documents = body.documents;
    if (!Array.isArray(documents) || documents.length > 1) {
        throw new HttpError(400, "documents must be an array containing at most one seller terms document");
    }
    const document = documents.length ? await publishedDocument(documents[0]) : null;
    return json(
        await syncMarketplaceTermsConfiguration({
            document,
            legacyVersion: document ? null : optionalText(body.legacyVersion, 200),
            legacyHash: document ? null : optionalHash(body.legacyHash),
            actorId: "cms-integration-sync",
        }),
    );
}

async function publishedDocument(value: unknown): Promise<JsonRecord> {
    if (!isRecord(value)) {
        throw new HttpError(400, "documents[0] must be an object");
    }
    assertOnlyKeys(value, ["key", "label", "consentText", "page"], "documents[0]");
    const documentKey = requiredText(value.key, "documents[0].key", 80);
    if (!/^[a-z][a-z0-9_.-]{1,79}$/.test(documentKey)) {
        throw new HttpError(422, "documents[0].key is invalid");
    }
    const label = requiredText(value.label, "documents[0].label", 200);
    const consentText = requiredText(value.consentText, "documents[0].consentText", 1_000);
    const snapshot = await materializePublishedMarketplaceTerms(value.page);
    const revisionHash = await sha256Hex(
        JSON.stringify({
            documentKey,
            label,
            consentText,
            page: JSON.parse(serializePublishedPage(snapshot.page)),
            contentHash: snapshot.contentHash,
        }),
    );
    return {
        documentKey,
        label,
        consentText,
        page: snapshot.page,
        publishedSnapshotUrl: snapshot.publishedSnapshotUrl,
        contentHash: snapshot.contentHash,
        revisionHash,
    };
}

function requiredText(value: unknown, name: string, maximum: number): string {
    if (typeof value !== "string") {
        throw new HttpError(400, `${name} is required`);
    }
    const normalized = value.trim();
    if (!normalized || normalized.length > maximum) {
        throw new HttpError(422, `${name} is invalid`);
    }
    return normalized;
}

function optionalText(value: unknown, maximum: number): string | null {
    if (value === undefined || value === null || value === "") {
        return null;
    }
    if (typeof value !== "string" || value.trim().length > maximum) {
        throw new HttpError(400, "legacyVersion is invalid");
    }
    return value.trim();
}

function optionalHash(value: unknown): string | null {
    const hash = optionalText(value, 64)?.toLowerCase() ?? null;
    if (hash && !/^[a-f0-9]{64}$/.test(hash)) {
        throw new HttpError(400, "legacyHash must be a SHA-256 hex digest");
    }
    return hash;
}

function assertOnlyKeys(value: JsonRecord, allowed: string[], name: string): void {
    const expected = new Set(allowed);
    const extra = Object.keys(value).find((key) => !expected.has(key));
    if (extra) {
        throw new HttpError(400, `${name}.${extra} is not allowed`);
    }
}

import type { MarketplaceTermsAcceptanceRow } from "../../../db/records/accounts.ts";
import { rest, restError } from "../../../db/postgrest.ts";
import { HttpError } from "../../../http/errors.ts";
import { isRecord } from "../../../shared/data.ts";
import type { JsonRecord } from "../../../shared/types.ts";

export type MarketplaceTermsExpectation = {
    version: string;
    hash: string;
};

export type MarketplaceTermsConfiguration = MarketplaceTermsExpectation & {
    mode: "legacy" | "published_page";
    documentKey?: string;
    label?: string;
    consentText?: string;
    page?: {
        id: string;
        path: string;
        title: string;
        description: string;
        content: string;
    };
    publishedSnapshotUrl?: string;
    updatedAt: string;
};

export type MarketplaceTermsRequirement = MarketplaceTermsExpectation & {
    mode: "legacy" | "published_page";
    documentKey?: string;
    label?: string;
    consentText?: string;
    page?: {
        id: string;
        path: string;
        title: string;
    };
};

export async function getCurrentMarketplaceTermsConfiguration(): Promise<MarketplaceTermsConfiguration | null> {
    const value = await callMarketplaceTermsRpc("get_current_marketplace_terms_configuration", {});
    if (value === null) {
        return null;
    }
    return marketplaceTermsConfiguration(value);
}

export async function syncMarketplaceTermsConfiguration(values: {
    document: JsonRecord | null;
    legacyVersion: string | null;
    legacyHash: string | null;
    actorId: string;
}): Promise<MarketplaceTermsConfiguration> {
    return marketplaceTermsConfiguration(
        await callMarketplaceTermsRpc("sync_marketplace_terms_configuration", {
            p_document: values.document,
            p_legacy_version: values.legacyVersion,
            p_legacy_hash: values.legacyHash,
            p_actor_id: values.actorId,
        }),
    );
}

export async function recordCurrentMarketplaceTermsAcceptance(
    userId: string,
    expected: MarketplaceTermsExpectation | null,
): Promise<MarketplaceTermsAcceptanceRow> {
    const value = await callMarketplaceTermsRpc("record_current_marketplace_terms_acceptance", {
        p_cms_user_id: userId,
        p_expected_version: expected?.version ?? null,
        p_expected_hash: expected?.hash ?? null,
    });
    if (!isRecord(value)) {
        throw new HttpError(502, "Supabase returned an invalid marketplace terms acceptance");
    }
    return value as MarketplaceTermsAcceptanceRow;
}

export function marketplaceTermsRequirement(
    configuration: MarketplaceTermsConfiguration | null,
): MarketplaceTermsRequirement | null {
    if (!configuration) {
        return null;
    }
    const requirement: MarketplaceTermsRequirement = {
        mode: configuration.mode,
        version: configuration.version,
        hash: configuration.hash,
    };
    if (
        configuration.mode === "published_page" &&
        configuration.documentKey &&
        configuration.label &&
        configuration.consentText &&
        configuration.page
    ) {
        return {
            ...requirement,
            documentKey: configuration.documentKey,
            label: configuration.label,
            consentText: configuration.consentText,
            page: {
                id: configuration.page.id,
                path: configuration.page.path,
                title: configuration.page.title,
            },
        };
    }
    return requirement;
}

export function marketplaceTermsExpectation(
    configuration: MarketplaceTermsConfiguration | null,
): MarketplaceTermsExpectation | null {
    return configuration ? { version: configuration.version, hash: configuration.hash } : null;
}

export function effectiveMarketplaceTermsExpectation(
    explicit: MarketplaceTermsExpectation | null,
    configuration: MarketplaceTermsConfiguration | null,
): MarketplaceTermsExpectation | null {
    return marketplaceTermsExpectation(configuration) ?? explicit;
}

async function callMarketplaceTermsRpc(name: string, body: JsonRecord): Promise<unknown> {
    const response = await rest(`rpc/${name}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
    });
    if (!response.ok) {
        throw await restError(response);
    }
    return response.json();
}

function marketplaceTermsConfiguration(value: unknown): MarketplaceTermsConfiguration {
    if (
        !isRecord(value) ||
        (value.mode !== "legacy" && value.mode !== "published_page") ||
        typeof value.version !== "string" ||
        !value.version ||
        typeof value.hash !== "string" ||
        !/^[a-f0-9]{64}$/.test(value.hash) ||
        typeof value.updatedAt !== "string"
    ) {
        throw new HttpError(502, "Supabase returned an invalid marketplace terms configuration");
    }
    if (value.mode === "legacy") {
        return {
            mode: value.mode,
            version: value.version,
            hash: value.hash,
            updatedAt: value.updatedAt,
        };
    }
    if (
        typeof value.documentKey !== "string" ||
        typeof value.label !== "string" ||
        typeof value.consentText !== "string" ||
        !isPublishedPage(value.page) ||
        typeof value.publishedSnapshotUrl !== "string"
    ) {
        throw new HttpError(502, "Supabase returned incomplete published marketplace terms");
    }
    return {
        mode: value.mode,
        version: value.version,
        hash: value.hash,
        documentKey: value.documentKey,
        label: value.label,
        consentText: value.consentText,
        page: value.page,
        publishedSnapshotUrl: value.publishedSnapshotUrl,
        updatedAt: value.updatedAt,
    };
}

function isPublishedPage(value: unknown): value is MarketplaceTermsConfiguration["page"] {
    return (
        isRecord(value) &&
        typeof value.id === "string" &&
        typeof value.path === "string" &&
        typeof value.title === "string" &&
        typeof value.description === "string" &&
        typeof value.content === "string"
    );
}

import { HttpError } from "../../../http/errors.ts";
import { isRecord } from "../../../shared/data.ts";
import type { JsonRecord } from "../../../shared/types.ts";
import { publishedPageContentHash, type PublishedPage } from "./canonical-page.ts";

const snapshotRoute = "/.cms/content/published-page-snapshot";
const maximumContentBytes = 2_000_000;

export async function materializePublishedMarketplaceTerms(value: unknown): Promise<{
    page: PublishedPage;
    publishedSnapshotUrl: string;
    contentHash: string;
}> {
    if (!isRecord(value)) {
        unavailableSnapshot();
    }
    const expectedPage = pageValue(value);
    const publishedSnapshotUrl = stringValue(value.publishedSnapshotUrl, 4_096);
    if (!isPublishedSnapshotUrl(publishedSnapshotUrl, expectedPage.id)) {
        unavailableSnapshot();
    }
    return {
        page: expectedPage,
        publishedSnapshotUrl,
        contentHash: await publishedPageContentHash(expectedPage),
    };
}

function pageValue(value: JsonRecord): PublishedPage {
    const id = stringValue(value.id, 512);
    const path = stringValue(value.path, 2_048);
    const title = stringValue(value.title, 500);
    const description = stringValue(value.description, 1_000, true);
    const content = stringValue(value.content, Number.MAX_SAFE_INTEGER);
    if (!id || !path.startsWith("/") || !title.trim() || !content.trim()) {
        unavailableSnapshot();
    }
    if (new TextEncoder().encode(content).byteLength > maximumContentBytes) {
        unavailableSnapshot();
    }
    return { id, path, title, description, content };
}

function isPublishedSnapshotUrl(value: string, pageId: string): boolean {
    try {
        const url = new URL(value);
        return (
            isAllowedOrigin(url) &&
            !url.username &&
            !url.password &&
            !url.hash &&
            url.pathname.endsWith(snapshotRoute) &&
            [...url.searchParams.keys()].every((key) => key === "id") &&
            url.searchParams.getAll("id").length === 1 &&
            url.searchParams.get("id") === pageId
        );
    } catch {
        return false;
    }
}

function isAllowedOrigin(url: URL): boolean {
    return (
        url.protocol === "https:" ||
        (url.protocol === "http:" &&
            (url.hostname === "localhost" ||
                url.hostname.endsWith(".localhost") ||
                url.hostname === "127.0.0.1" ||
                url.hostname === "[::1]"))
    );
}

function stringValue(value: unknown, maximum: number, allowEmpty = false): string {
    if (typeof value !== "string" || value.length > maximum || (!allowEmpty && !value)) {
        unavailableSnapshot();
    }
    return value;
}

function unavailableSnapshot(): never {
    throw new HttpError(409, "MARKETPLACE_TERMS_DOCUMENT_NOT_AVAILABLE");
}

import { updateAccountRow } from "../../db/repositories/accounts.ts";
import { publicAccountStatus } from "../../domain/accounts/presentation.ts";
import { requireCmsRequest } from "../../http/auth.ts";
import { readJsonObject, requiredString } from "../../http/body/index.ts";
import { requiredQueryText, validHttpsUrl } from "../../http/query.ts";
import { json } from "../../http/responses.ts";
import { createAccountLink, createAccountSession } from "../../provider/accounts/onboarding.ts";
import { stringAt, unixTimestampAt } from "../../shared/data.ts";
import type { JsonRecord } from "../../shared/types.ts";
import { ensureConnectedAccountForUser } from "./lifecycle.ts";

export async function connectOnboarding(request: Request): Promise<Response> {
    const { userId } = requireCmsRequest(request);
    const body = await readJsonObject(request);
    return json(await createOnboardingForUser(userId, body));
}

export async function connectOnboardingSession(request: Request): Promise<Response> {
    const { userId } = requireCmsRequest(request);
    const body = await readJsonObject(request);
    return json(await createOnboardingSessionForUser(userId, body));
}

export async function adminCreateOnboarding(request: Request): Promise<Response> {
    requireCmsRequest(request, { requireUser: false });
    const userId = requiredQueryText(request, "userId", 200);
    const body = await readJsonObject(request);
    return json(await createOnboardingForUser(userId, body));
}

export async function adminCreateOnboardingSession(request: Request): Promise<Response> {
    requireCmsRequest(request, { requireUser: false });
    const userId = requiredQueryText(request, "userId", 200);
    const body = await readJsonObject(request);
    return json(await createOnboardingSessionForUser(userId, body));
}

async function createOnboardingForUser(userId: string, body: JsonRecord): Promise<JsonRecord> {
    const returnUrl = validHttpsUrl(requiredString(body, "returnUrl", 2048), "returnUrl");
    const refreshUrl = validHttpsUrl(requiredString(body, "refreshUrl", 2048), "refreshUrl");
    const { account, stripeAccountId, stripeAccountApiVersion } = await ensureConnectedAccountForUser(userId, body);
    const link = await createAccountLink(stripeAccountId, stripeAccountApiVersion, returnUrl, refreshUrl);
    const updated =
        (await updateAccountRow(userId, {
            onboarding_status: "link_created",
            last_onboarding_started_at: new Date().toISOString(),
        })) ?? account;

    return {
        ...publicAccountStatus(updated, userId),
        url: stringAt(link, "url"),
        expiresAt: unixTimestampAt(link, "expires_at"),
    };
}

async function createOnboardingSessionForUser(userId: string, body: JsonRecord): Promise<JsonRecord> {
    const { account, stripeAccountId } = await ensureConnectedAccountForUser(userId, body);
    const session = await createAccountSession(stripeAccountId);
    const updated =
        (await updateAccountRow(userId, {
            onboarding_status: "onboarding_started",
            last_onboarding_started_at: new Date().toISOString(),
        })) ?? account;

    return {
        ...publicAccountStatus(updated, userId),
        clientSecret: session.client_secret,
        expiresAt: session.expires_at,
    };
}

