type PlatformPayoutProtectionInput = {
    changeId: string;
    minimumBalanceEur: number | null;
    liabilityRevision: number;
    decreaseAuthorizationId: string | null;
    delayDaysOverride: number | null;
    debitNegativeBalances: boolean | null;
    reason: string | null;
};

export async function readPlatformPayoutProtectionInput(request: Request): Promise<PlatformPayoutProtectionInput> {
    const body = await readJsonObject(request);
    assertAllowedKeys(body, [
        "platformPayoutControlChangeId",
        "minimumBalanceEur",
        "delayDaysOverride",
        "debitNegativeBalances",
        "reason",
        "liabilityRevision",
        "decreaseAuthorizationId",
    ]);
    const changeId = requiredString(body, "platformPayoutControlChangeId", 200);
    const minimumBalanceEur = optionalNonNegativeInteger(body, "minimumBalanceEur");
    const liabilityRevision = requiredInteger(body, "liabilityRevision");
    if (!Number.isSafeInteger(liabilityRevision) || liabilityRevision < 0) {
        throw new HttpError(400, "liabilityRevision must be a non-negative safe integer");
    }
    const decreaseAuthorizationId = optionalText(body, "decreaseAuthorizationId", 64);
    if (
        decreaseAuthorizationId &&
        !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(decreaseAuthorizationId)
    ) {
        throw new HttpError(400, "decreaseAuthorizationId must be a UUID");
    }
    const delayDaysOverride = optionalNonNegativeInteger(body, "delayDaysOverride");
    const debitNegativeBalances = optionalBoolean(body, "debitNegativeBalances");
    const reason = optionalText(body, "reason", 500);
    if (delayDaysOverride !== null && delayDaysOverride > 31) {
        throw new HttpError(400, "delayDaysOverride must be between zero and 31");
    }
    return {
        changeId,
        minimumBalanceEur,
        liabilityRevision,
        decreaseAuthorizationId,
        delayDaysOverride,
        debitNegativeBalances,
        reason,
    };
}

import { platformPayoutControlRpc } from "../../db/repositories/payout-controls.ts";
import type { JsonRecord } from "../../shared/types.ts";

const leaseRetryCount = 20;
const leaseRetryDelayMs = 100;

type PlatformPayoutProtectionClaimInput = {
    owner: string;
    requiredMinimumAmount: number;
    liabilityRevision: number;
    decreaseAuthorizationId: string | null;
};

export async function claimPlatformPayoutProtectionLease({
    owner,
    requiredMinimumAmount,
    liabilityRevision,
    decreaseAuthorizationId,
}: PlatformPayoutProtectionClaimInput): Promise<JsonRecord> {
    const body = {
        p_owner: owner,
        p_required_minimum_amount: requiredMinimumAmount,
        p_liability_revision: liabilityRevision,
        p_decrease_authorization_id: decreaseAuthorizationId,
    };
    let claim = await platformPayoutControlRpc("claim_platform_payout_protection", body);
    for (let retry = 0; claim.claimed !== true && retry < leaseRetryCount; retry++) {
        await pause(leaseRetryDelayMs);
        claim = await platformPayoutControlRpc("claim_platform_payout_protection", body);
    }
    return claim;
}

function pause(milliseconds: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

import { insertRow } from "../../db/postgrest.ts";
import {
    reservePlatformFinancialOperation,
    updateFinancialOperation,
} from "../../db/repositories/financial-operations.ts";
import { platformPayoutControlRpc } from "../../db/repositories/payout-controls.ts";
import type { FinancialOperationRow, PlatformPayoutControlRow } from "../../db/records/operations.ts";
import { balanceSettingsMatchRequest, publicBalanceSettings } from "../../domain/accounts/payout-settings.ts";
import { requireCmsRequest } from "../../http/auth.ts";
import { HttpError } from "../../http/errors.ts";
import { json } from "../../http/responses.ts";
import { retrievePlatformBalanceSettings, updateBalanceSettings } from "../../provider/accounts/balances.ts";
import { digest, stableStripeIdempotencyKey } from "../../shared/crypto.ts";
import { errorMessage, numberAt, objectAt, stripUndefined } from "../../shared/data.ts";
import { protectedPlatformPayoutInterval } from "../../shared/runtime.ts";
import type { JsonRecord } from "../../shared/types.ts";
import { readPlatformPayoutProtectionInput } from "./platform-protection-input.ts";
import { claimPlatformPayoutProtectionLease } from "./platform-protection-lease.ts";

type PlatformPayoutProtectionDependencies = {
    platformPayoutControl(result: JsonRecord): PlatformPayoutControlRow;
};

export function createConfigurePlatformPayoutProtection({
    platformPayoutControl,
}: PlatformPayoutProtectionDependencies): (request: Request) => Promise<Response> {
    return async function configurePlatformPayoutProtection(request) {
        requireCmsRequest(request, { requireUser: false });
        const {
            changeId,
            minimumBalanceEur,
            liabilityRevision,
            decreaseAuthorizationId,
            delayDaysOverride,
            debitNegativeBalances,
            reason,
        } = await readPlatformPayoutProtectionInput(request);
        const owner = crypto.randomUUID();
        let claim = await claimPlatformPayoutProtectionLease({
            owner,
            requiredMinimumAmount: minimumBalanceEur ?? 0,
            liabilityRevision,
            decreaseAuthorizationId,
        });
        if (claim.claimed !== true) {
            throw new HttpError(
                409,
                "platform payout protection is already being synchronized; the higher requirement was recorded",
            );
        }
        let operation: FinancialOperationRow | null = null;
        let appliedMinimum = 0;
        let appliedDecreaseAuthorizationId: string | null = null;
        try {
            for (let attempt = 0; attempt < 5; attempt++) {
                const control = platformPayoutControl(claim);
                appliedDecreaseAuthorizationId = control.decrease_authorization_id;
                const current = await retrievePlatformBalanceSettings();
                const currentMinimum =
                    numberAt(
                        objectAt(objectAt(objectAt(current, "payments"), "payouts"), "minimum_balance_by_currency"),
                        "eur",
                    ) ?? 0;
                appliedMinimum = control.decrease_authorization_id
                    ? control.required_minimum_amount
                    : Math.max(control.required_minimum_amount, control.provider_minimum_amount, currentMinimum);
                const operationRequest = stripUndefined({
                    scope: "platform",
                    interval: protectedPlatformPayoutInterval,
                    minimumBalanceEur: appliedMinimum,
                    delayDaysOverride: delayDaysOverride ?? undefined,
                    debitNegativeBalances: debitNegativeBalances ?? undefined,
                    reason: reason ?? undefined,
                    commerceLiabilityRevision: control.liability_revision,
                    commerceRequestedDecreaseAuthorizationId: decreaseAuthorizationId ?? undefined,
                    commerceAppliedDecreaseAuthorizationId: appliedDecreaseAuthorizationId ?? undefined,
                });
                const requestHash = await digest(JSON.stringify(operationRequest));
                const businessKey = [
                    "platform-payout-protection",
                    control.liability_revision,
                    appliedMinimum,
                    requestHash,
                ].join(":");
                operation = await reservePlatformFinancialOperation({
                    businessKey,
                    operationType: "payout_schedule_update",
                    request: operationRequest,
                });
                let provider = current;
                if (!balanceSettingsMatchRequest(current, operationRequest)) {
                    await updateFinancialOperation(operation.id, {
                        status: "processing",
                        claimed_at: new Date().toISOString(),
                        attempt_count: operation.attempt_count + 1,
                    });
                    provider = await updateBalanceSettings(
                        null,
                        operationRequest,
                        await stableStripeIdempotencyKey("platform-payout-protection", businessKey),
                    );
                }
                if (!balanceSettingsMatchRequest(provider, operationRequest)) {
                    throw new Error("Stripe did not confirm the required platform payout protection");
                }
                if (operation.status !== "succeeded" || provider !== current) {
                    await updateFinancialOperation(operation.id, {
                        status: "succeeded",
                        response: provider,
                        last_error: null,
                        completed_at: new Date().toISOString(),
                    });
                }
                const completed = await platformPayoutControlRpc("complete_platform_payout_protection", {
                    p_owner: owner,
                    p_expected_liability_revision: control.liability_revision,
                    p_applied_minimum_amount: appliedMinimum,
                    p_succeeded: true,
                    p_error: null,
                });
                if (completed.accepted !== true) {
                    throw new HttpError(409, "platform payout protection lease was superseded");
                }
                if (completed.needsReapply === true) {
                    claim = { claimed: true, control: objectAt(completed, "control") };
                    continue;
                }
                return json({
                    platformPayoutControlChangeId: changeId,
                    providerOperationId: operation.id,
                    liabilityRevision: platformPayoutControl(completed).liability_revision,
                    appliedMinimumBalanceEur: appliedMinimum,
                    decreaseAuthorizationId: appliedDecreaseAuthorizationId,
                    payoutControl: publicBalanceSettings(provider),
                    providerSnapshot: provider,
                });
            }
            throw new Error("platform payout requirements changed repeatedly during provider synchronization");
        } catch (error) {
            const message = errorMessage(error);
            if (operation) {
                await updateFinancialOperation(operation.id, { status: "manual_review", last_error: message }).catch(
                    () => null,
                );
            }
            const control = platformPayoutControl(claim);
            await platformPayoutControlRpc("complete_platform_payout_protection", {
                p_owner: owner,
                p_expected_liability_revision: control.liability_revision,
                p_applied_minimum_amount: appliedMinimum,
                p_succeeded: false,
                p_error: message,
            }).catch(() => null);
            await insertRow<JsonRecord>("provider_exceptions", "id", {
                operation_id: operation?.id ?? null,
                exception_type: "platform_payout_protection_ambiguous",
                severity: "critical",
                message,
                details: {
                    platformPayoutControlChangeId: changeId,
                    requestedMinimumBalanceEur: minimumBalanceEur ?? 0,
                    liabilityRevision: control.liability_revision,
                },
            }).catch(() => null);
            throw error;
        }
    };
}

import {
    assertAllowedKeys,
    optionalBoolean,
    optionalNonNegativeInteger,
    optionalText,
    readJsonObject,
    requiredString,
} from "../../http/body/index.ts";
import { HttpError } from "../../http/errors.ts";
import { optionalMonthlyPayoutDays, optionalWeeklyPayoutDays, requiredPayoutInterval } from "../../http/payouts.ts";

export type SellerPayoutScheduleInput = {
    userId: string;
    payoutScheduleChangeId: string;
    interval: "manual" | "daily" | "weekly" | "monthly";
    weeklyPayoutDays: string[];
    monthlyPayoutDays: number[];
    minimumBalanceEur: number | null;
    delayDaysOverride: number | null;
    debitNegativeBalances: boolean | null;
    reason: string | null;
};

export async function readSellerPayoutScheduleInput(request: Request): Promise<SellerPayoutScheduleInput> {
    const body = await readJsonObject(request);
    assertAllowedKeys(body, [
        "userId",
        "payoutScheduleChangeId",
        "payoutSchedule",
        "interval",
        "weeklyPayoutDays",
        "monthlyPayoutDays",
        "minimumBalanceEur",
        "delayDaysOverride",
        "debitNegativeBalances",
        "reason",
    ]);
    const userId = requiredString(body, "userId", 200);
    const payoutScheduleChangeId = requiredString(body, "payoutScheduleChangeId", 200);
    const configuredSchedule = optionalText(body, "payoutSchedule", 200);
    const hasLegacySchedule =
        body.interval !== undefined || body.weeklyPayoutDays !== undefined || body.monthlyPayoutDays !== undefined;
    if (configuredSchedule && hasLegacySchedule) {
        throw new HttpError(
            400,
            "payoutSchedule cannot be combined with interval, weeklyPayoutDays, or monthlyPayoutDays",
        );
    }
    const schedule = configuredSchedule
        ? parseConfiguredPayoutSchedule(configuredSchedule)
        : {
              interval: requiredPayoutInterval(body, "interval"),
              weeklyPayoutDays: optionalWeeklyPayoutDays(body, "weeklyPayoutDays"),
              monthlyPayoutDays: optionalMonthlyPayoutDays(body, "monthlyPayoutDays"),
          };
    const { interval, weeklyPayoutDays, monthlyPayoutDays } = schedule;
    const minimumBalanceEur = optionalNonNegativeInteger(body, "minimumBalanceEur");
    const delayDaysOverride = optionalNonNegativeInteger(body, "delayDaysOverride");
    const debitNegativeBalances = optionalBoolean(body, "debitNegativeBalances");
    const reason = optionalText(body, "reason", 500);
    if (delayDaysOverride !== null && delayDaysOverride > 31) {
        throw new HttpError(400, "delayDaysOverride must be between zero and 31");
    }
    if (interval === "weekly" && weeklyPayoutDays.length === 0) {
        throw new HttpError(400, "weeklyPayoutDays is required for a weekly payout schedule");
    }
    if (interval !== "weekly" && weeklyPayoutDays.length > 0) {
        throw new HttpError(400, "weeklyPayoutDays is allowed only for a weekly payout schedule");
    }
    if (interval === "monthly" && monthlyPayoutDays.length === 0) {
        throw new HttpError(400, "monthlyPayoutDays is required for a monthly payout schedule");
    }
    if (interval !== "monthly" && monthlyPayoutDays.length > 0) {
        throw new HttpError(400, "monthlyPayoutDays is allowed only for a monthly payout schedule");
    }
    return {
        userId,
        payoutScheduleChangeId,
        interval,
        weeklyPayoutDays,
        monthlyPayoutDays,
        minimumBalanceEur,
        delayDaysOverride,
        debitNegativeBalances,
        reason,
    };
}

function parseConfiguredPayoutSchedule(value: string): {
    interval: SellerPayoutScheduleInput["interval"];
    weeklyPayoutDays: string[];
    monthlyPayoutDays: number[];
} {
    if (value === "daily" || value === "manual") {
        return { interval: value, weeklyPayoutDays: [], monthlyPayoutDays: [] };
    }
    const [interval, days, unexpected] = value.split(":");
    if (unexpected !== undefined || !days) {
        throw invalidConfiguredPayoutSchedule();
    }
    const entries = days.split(",").map((entry) => entry.trim());
    if (entries.some((entry) => !entry)) {
        throw invalidConfiguredPayoutSchedule();
    }
    if (interval === "weekly") {
        return {
            interval,
            weeklyPayoutDays: optionalWeeklyPayoutDays({ payoutSchedule: entries }, "payoutSchedule"),
            monthlyPayoutDays: [],
        };
    }
    if (interval === "monthly") {
        if (entries.some((entry) => !/^(?:[1-9]|[12][0-9]|3[01])$/.test(entry))) {
            throw invalidConfiguredPayoutSchedule();
        }
        return {
            interval,
            weeklyPayoutDays: [],
            monthlyPayoutDays: optionalMonthlyPayoutDays({ payoutSchedule: entries.map(Number) }, "payoutSchedule"),
        };
    }
    throw invalidConfiguredPayoutSchedule();
}

function invalidConfiguredPayoutSchedule(): HttpError {
    return new HttpError(400, "payoutSchedule must be daily, manual, weekly:<weekdays>, or monthly:<days-of-month>");
}

