before update or delete on stripe_connect.marketplace_terms_acceptances
for each row execute function stripe_connect.reject_marketplace_terms_acceptance_mutation();

drop trigger if exists marketplace_terms_versions_immutable
    on stripe_connect.marketplace_terms_versions;
create trigger marketplace_terms_versions_immutable
before update or delete on stripe_connect.marketplace_terms_versions
