    p_business_key text,
    p_operation_type text,
    p_request jsonb
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare v_operation stripe_connect.financial_operations%rowtype;
begin
    if p_business_key is null or length(btrim(p_business_key)) = 0 then
        raise exception 'validation: business key is required';
